    FillRandom(&rng_.s_, sizeof(rng_.s_));
  }

  uint64_t Next()
  {
    return rng_.Next();
  }

  double Normal(const double mean, const double stddev)
  {
    double v1, v2, s;
    do
    {
      auto u1 = Next() / std::exp2(64);
      auto u2 = Next() / std::exp2(64);
      v1 = 2*u1 - 1;
      v2 = 2*u2 - 1;
      s = v1*v1 + v2*v2;
    }
    while(s >= 1);
    if(s == 0) return 0;
    return mean + stddev * (v1 * std::sqrt(-2 * std::log(s) / s));
