    {
            #pragma omp task
            {
                recursive_task(level-1);
            }
             #pragma omp task 
            {
                recursive_task(level-1);
            }
            #pragma omp taskwait
    }
}

int main()
{
    double time;

    gettimeofday(&t1, 0);

#pragma omp parallel num_threads(4)
    {
#pragma omp single
        {
            recursive_task(2);
        }
    }

