Mixing OpenMP and any other threading library ( pthreads , Win32 threading, etc.) might not be a good idea. The OpenMP run-time might be written with the presumption that it is fully in control of threading and might not support parallel regions being run concurrently (e.g. it might use global variables like semaphores to control the thread pools). A better pure OpenMP way to implement this would be: #include <iostream>
#include <omp.h>

using namespace std;

void hello(int a) {

    #pragma omp parallel for
    for (int i=0;i<5;++i) {
        #pragma omp critical
        cout << "Hello from " << a << "! " << "OMP thread iter " << i << endl;
    }

    cout << "About to return from hello function" << endl;
}

int main (int argc, char ** argv) {

    omp_set_nested(1);

    #pragma omp parallel sections num_threads(2)
    {
       #pragma omp section
       {
           hello(1);
       }
       #pragma omp section
       {
           hello(2);
       }
    }

    return 0;
} The call to omp_set_nested() is needed in order to enable nested parallelism which is disabled by default.

